  'privacy.cookies.body': 'เราใช้คุกกี้ที่จำเป็นและการจัดเก็บข้อมูลท้องถิ่นเพื่อรักษาเซสชันของคุณ, จำการตั้งค่าของคุณ (ธีม, ภาษา) และมอบประสบการณ์ที่ราบรื่น เราจะไม่ใช้คุกกี้ติดตามจากบุคคลที่สาม',
