  'plans.faqChangePlanAnswer': 'ใช่! หากคุณอัปเกรดจาก Plus เป็น Pro จะมีการเรียกเก็บเฉพาะส่วนต่างที่เหมาะสม หากคุณลดระดับ แผนปัจจุบันจะยังคงอยู่จนถึงสิ้นสุดระยะเวลา.',
